import { _ } from '@splunk/ui-utils/i18n';
import Provider from '@splunk/visualization-context/Provider';

import { b64EncodeUnicode } from '@splunk/dashboard-utils';

type PreserveAspectRatioValue = 'none' | 'meet';

const SVG_DATA_URI_PREFIX = 'data:image/svg+xml;base64,';

const decodeBase64Unicode = (value: string): string =>
    decodeURIComponent(
        Array.from(globalThis.atob(value), (char) =>
            `%${char.charCodeAt(0).toString(16).padStart(2, '0')}`,
        ).join(''),
    );

const withPreserveAspectRatio = (
    dataURI: string,
    preserveAspectRatio?: PreserveAspectRatioValue,
): string => {
    if (!preserveAspectRatio || !dataURI.startsWith(SVG_DATA_URI_PREFIX)) {
        return dataURI;
    }

    const svgMarkup = decodeBase64Unicode(dataURI.slice(SVG_DATA_URI_PREFIX.length));
    const updatedSvgMarkup = svgMarkup.replace(
        /<svg\b([^>]*)>/,
        (_match, attributes) => {
            if (/\spreserveAspectRatio=/.test(attributes)) {
                return `<svg${attributes.replace(
                    /preserveAspectRatio="[^"]*"/,
                    `preserveAspectRatio="${preserveAspectRatio}"`,
                )}>`;
            }

            return `<svg${attributes} preserveAspectRatio="${preserveAspectRatio}">`;
        },
    );

    return `${SVG_DATA_URI_PREFIX}${b64EncodeUnicode(updatedSvgMarkup)}`;
};

interface Icon {
    dataURI: string;
    metaData: Record<string, string>;
    preserveAspectRatio?: PreserveAspectRatioValue;
}

type IconMap = Record<string, Icon>;

interface IconListItem {
    id: string;
    metaData?: Record<string, string>;
}

