const isSearched = (search: string | null, iconMeta: Record<string, string>): boolean => {
    return (
        !!search &&
        Object.keys(iconMeta).some((attr) => {
            const iconMetaValue = iconMeta[attr].toLowerCase();
            return iconMetaValue.indexOf(search.toLowerCase()) > -1;
        })
    );
};

const createIcon = (
    id: string,
    iconMeta: Record<string, string>,
    meta?: string[],
): IconListItem => {
    const icon: IconListItem = { id };
    if (meta?.length) {
        meta.forEach((attr) => {
            if (iconMeta[attr]) {
                icon.metaData ??= {};
                icon.metaData[attr] = iconMeta[attr];
            }
        });
    }

    return icon;
};

const createConfiguredIcon = (icon: Icon): Icon => {
    return {
        ...icon,
        dataURI: withPreserveAspectRatio(icon.dataURI, icon.preserveAspectRatio),
    };
};

/**
 * a local icon provider
 */
class SEIIconProvider extends Provider {
    iconList: IconMap;

    constructor({ iconList }: { iconList?: IconMap } = {}) {
        super();

        const combinedIcons = {
            ...iconList,
            ...defaultIconList,
        };

        this.iconList = Object.keys(combinedIcons).reduce((configuredIcons, id) => {
            configuredIcons[id] = createConfiguredIcon(combinedIcons[id]);
                return configuredIcons;
        }, {} as IconMap);
    }

    /**
     * return provider type
     * @return {String} 'splunk-default'
     */
    getType(): string {
        return 'sei-default';
    }

    /**
     * upload one new icon
     */
    async upload(): Promise<void> {
        throw new Error(_('Can not upload icons to the standard icon provider.'));
    }

    /**
     * get one icon by icon id
     */
    async getById(id: string): Promise<Icon> {
        if (this.iconList[id]) {
            return this.iconList[id];
        }
        throw new Error(_('The icon is not found.'));
    }

    /**
     * get all icon ids
     * @params options
     * @params options.meta   a list of meta data attribute that would be returned with each id
     * @params options.search  a search string to filter the returned icons
     */
    async listIds({
        offset = 0,
        count = 100,
        meta = [],
        search = null,
    }: {
        offset?: number;
        count?: number;
        meta?: string[];
        search?: string | null;
    } = {}): Promise<IconListItem[]> {
        try {
            const icons = this.iconList;
            const results: IconListItem[] = [];

            Object.keys(icons)
                .sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }))
                .slice(offset, count)
                .forEach((id) => {
                    const iconMeta = icons[id].metaData ?? {};
                    // If search is a valid string, return the icon with matched meta data
                    const isSearchedIcon = isSearched(search, iconMeta);

                    if (!search || isSearchedIcon) {
                        results.push(createIcon(id, iconMeta, meta));
                    }
                });

            return results;
        } catch {
            throw new Error(_('The icon ids cannot be listed.'));
        }
    }

    /**
     * delete an icon by icon id
     */
    async deleteById(): Promise<void> {
        throw new Error(_('The icon cannot be deleted.'));
    }
}

export default SEIIconProvider;
